    [LibraryImport("jade_native", EntryPoint = "SDL_KillProcess")]
    [UnmanagedCallConv(CallConvs = [typeof(CallConvCdecl)])]
    [return: MarshalAs(UnmanagedType.U1)]
    public static partial bool KillProcess(Process process, [MarshalAs(UnmanagedType.U1)] bool force);

    /// <summary>Wait for a process to finish.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_WaitProcess</c>.</para>
    /// <para>This can be called multiple times to get the status of a process.</para>
    /// <para>
    /// The exit code will be the exit code of the process if it terminates normally, a negative signal if it terminated
    /// due to a signal, or -255 otherwise. It will not be changed if the process is still running.
    /// </para>
    /// <para>
    /// If you create a process with standard output piped to the application (<c>pipe_stdio</c> being true) then you
    /// should read all of the process output before calling SDL_WaitProcess(). If you don't do this the process might
    /// be blocked indefinitely waiting for output to be read and SDL_WaitProcess() will never return true;
    /// </para>
    /// <para>Thread safety: This function is not thread safe.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// <para>
    /// See also: <c>SDL_CreateProcess</c>, <c>SDL_CreateProcessWithProperties</c>, <c>SDL_KillProcess</c>,
    /// <c>SDL_DestroyProcess</c>.
    /// </para>
    /// </remarks>
    /// <param name="process">The process to wait for.</param>
    /// <param name="block">If true, block until the process finishes; otherwise, report on the process' status.</param>
    /// <param name="exitcode">
    /// a pointer filled in with the process exit code if the process has exited, may be NULL.
    /// </param>
    /// <returns>true if the process exited, false otherwise.</returns>
    [LibraryImport("jade_native", EntryPoint = "SDL_WaitProcess")]
    [UnmanagedCallConv(CallConvs = [typeof(CallConvCdecl)])]
    [return: MarshalAs(UnmanagedType.U1)]
    public static partial bool WaitProcess(Process process, [MarshalAs(UnmanagedType.U1)] bool block, int* exitcode);

    /// <summary>Wait for a process to finish.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_WaitProcess</c>.</para>
    /// <para>This can be called multiple times to get the status of a process.</para>
    /// <para>
    /// The exit code will be the exit code of the process if it terminates normally, a negative signal if it terminated
    /// due to a signal, or -255 otherwise. It will not be changed if the process is still running.
    /// </para>
    /// <para>
    /// If you create a process with standard output piped to the application (<c>pipe_stdio</c> being true) then you
    /// should read all of the process output before calling SDL_WaitProcess(). If you don't do this the process might
    /// be blocked indefinitely waiting for output to be read and SDL_WaitProcess() will never return true;
    /// </para>
    /// <para>Thread safety: This function is not thread safe.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// <para>
    /// See also: <c>SDL_CreateProcess</c>, <c>SDL_CreateProcessWithProperties</c>, <c>SDL_KillProcess</c>,
    /// <c>SDL_DestroyProcess</c>.
    /// </para>
    /// </remarks>
    /// <param name="process">The process to wait for.</param>
    /// <param name="block">If true, block until the process finishes; otherwise, report on the process' status.</param>
    /// <param name="exitcode">
    /// a pointer filled in with the process exit code if the process has exited, may be NULL.
    /// </param>
    /// <returns>true if the process exited, false otherwise.</returns>
    public static bool WaitProcess(Process process, bool block, out int exitcode)
    {
        exitcode = default;
        fixed (int* exitcodePtr = &exitcode)
        {
            return WaitProcess(process, block, exitcodePtr);
        }
    }

    /// <summary>Destroy a previously created process object.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_DestroyProcess</c>.</para>
    /// <para>
    /// Note that this does not stop the process, just destroys the SDL object used to track it. If you want to stop the
    /// process you should use SDL_KillProcess().
    /// </para>
    /// <para>Thread safety: This function is not thread safe.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// <para>See also: <c>SDL_CreateProcess</c>, <c>SDL_CreateProcessWithProperties</c>, <c>SDL_KillProcess</c>.</para>
    /// </remarks>
    /// <param name="process">The process object to destroy.</param>
    [LibraryImport("jade_native", EntryPoint = "SDL_DestroyProcess")]
    [UnmanagedCallConv(CallConvs = [typeof(CallConvCdecl)])]
    public static partial void DestroyProcess(Process process);
}
